// Code generated by packages/kit-compose/src/organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
/**
 * Features as cards under a centered heading. Axes: item (picture: a picture on top, then the title, the text
 * and a read link; panel: a muted panel with a large glyph on top, then the title and the text), cols (3, 4),
 * tone.
 */
import { type ReactNode } from "react";
import { Box, Card, CardContent, Text, Title } from "../compose";
import { LucideIcon } from "../icons/LucideIcon";
import { EmptyState } from "../components/empty-state";
import { MediaFrame } from "../components/media-frame";
import { MenuEntry } from "../components/menu-entry";
import { SectionFrame } from "../components/section-frame";
import type { Feature } from "./feature-grid.types";

export type FeatureShowcaseProps = {
  id: string;
  title: string;
  lead?: string;
  features: Feature[];
  empty?: string;
  more: string;
  item?: "picture" | "panel";
  cols?: "3" | "4";
  tone?: "default" | "muted";
  landmarkLabel?: string;
};

export function FeatureShowcase({
  id,
  title,
  lead = "",
  features,
  empty = "",
  more,
  item = "picture",
  cols = "3",
  tone = "default",
  landmarkLabel,
}: FeatureShowcaseProps) {
  return (
    <SectionFrame id={id} title={title} lead={lead} tone={tone} align="center" landmarkLabel={landmarkLabel}>
      {((features?.length ?? 0) === 0) ? (
        <EmptyState icon="layout-grid" title={empty} />
      ) : (
        <Box
          className={
            (cols as string) === "4" ? "grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-4"
            : "grid grid-cols-1 gap-6 text-start sm:grid-cols-2 lg:grid-cols-3"
          }
        >
          {(features ?? []).map((f) => (
            <Card key={f.id} variant="default" className="h-full gap-4 overflow-hidden" data-testid="showcase-card">
              {((item as string) === "picture") ? (
                <MediaFrame alt={f.title} />
              ) : (
                <Box
                  className="flex aspect-video items-center justify-center rounded bg-muted text-foreground"
                  data-testid="showcase-panel"
                >
                  <LucideIcon name={f.icon} size={32} />
                </Box>
              )}
              <CardContent className="flex flex-1 flex-col gap-2">
                <Title as={3} size="base" weight="semibold">
                  {f.title}
                </Title>
                <Text size="sm" className="text-muted-foreground">
                  {f.text}
                </Text>
                {((item as string) === "picture") ? (
                  <MenuEntry href={f.href} className="mt-auto gap-2 pt-2 text-sm font-medium" size="sm" testid="read">
                    {more}
                    <LucideIcon name="arrow-right" size={16} />
                  </MenuEntry>
                ) : null}
              </CardContent>
            </Card>
          ))}
        </Box>
      )}
    </SectionFrame>
  );
}
